# Check the equation: a^3 * (b^3 + c^3) = 2012 * (a * b * c + 2)
solutions = []

# Check a=1
a = 1
for b in range(1, 11):
    for c in range(b, 11):
        LHS = a**3 * (b**3 + c**3)
        RHS = 2012 * (a * b * c + 2)
        if LHS == RHS:
            solutions.append((a, b, c))

# Check a=2
a = 2
for b in range(2, 11):
    for c in range(b, 11):
        LHS = a**3 * (b**3 + c**3)
        RHS = 2012 * (a * b * c + 2)
        if LHS == RHS:
            solutions.append((a, b, c))

print("Solutions found (a=1, a<=10, b<=10, c<=10):")
print(solutions)
